package com.mirigangneung.route.service;import com.mirigangneung.infrastructure.kakao.KakaoRouteClient;import com.mirigangneung.route.dto.*;import org.springframework.stereotype.Service;@Service public class RouteService{private final KakaoRouteClient c;public RouteService(KakaoRouteClient x){c=x;}public WalkingRouteResponse walking(WalkingRouteRequest r){var x=c.walking(r.origin().latitude(),r.origin().longitude(),r.destination().latitude(),r.destination().longitude());return new WalkingRouteResponse(x.distanceMeters(),x.durationSeconds(),x.polyline());}}
